/**
 * Outlook Stream Row & Schema Normalizer
 * Normalizes email ingestion streams into structured tabular records
 * with extracted senders, subjects, financial amounts, and urgency categories.
 */
async function process(inputs = {}, state = {}) {
  const emails = Array.isArray(inputs.emails) 
    ? inputs.emails 
    : Array.isArray(inputs.data) 
    ? inputs.data 
    : [
        { id: 'MAIL-101', sender: 'billing@aws.amazon.com', subject: 'Invoice #AWS-99102 Available', date: '2024-10-28', snippet: 'Your monthly bill for $4,120.50 is ready.' },
        { id: 'MAIL-102', sender: 'security@okta.com', subject: 'Urgent: Suspicious login from CY', date: '2024-10-28', snippet: 'MFA challenge failed 3 times.' },
        { id: 'MAIL-103', sender: 'partner@merck.com', subject: 'Protocol NSCLC amendment approved', date: '2024-10-28', snippet: 'Cohort expansion approved by IRB.' }
      ];

  const records = emails.map(m => {
    const isInvoice = /invoice|bill|payment|amount/i.test(m.subject + ' ' + m.snippet);
    const isAlert = /urgent|suspicious|alert|breach|failed/i.test(m.subject + ' ' + m.snippet);
    return {
      mailId: m.id,
      sender: m.sender,
      subject: m.subject,
      category: isInvoice ? 'FINANCE' : isAlert ? 'SECURITY' : 'CORRESPONDENCE',
      status: isAlert ? 'URGENT_ACTION' : 'NORMALIZED',
      ingestedAt: new Date().toISOString()
    };
  });

  return {
    summary: {
      totalEmails: emails.length,
      financeAlerts: records.filter(r => r.category === 'FINANCE').length,
      securityAlerts: records.filter(r => r.category === 'SECURITY').length
    },
    records
  };
}
